  inset: 0;
  z-index: 60;
  pointer-events: none;
}

.stick-zone {
  position: absolute;
  left: calc(18px + var(--safe-l));
  bottom: calc(20px + var(--safe-b));
  width: 132px;
  height: 132px;
  pointer-events: auto;
  touch-action: none;
}

.stick-base {
