  box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.45);
}

.stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 52px;
  height: 52px;
  margin: -26px;
  border-radius: 50%;
  background: rgba(242, 228, 196, 0.5);
