  right: calc(22px + var(--safe-r));
  bottom: calc(28px + var(--safe-b));
  width: 78px;
  height: 78px;
  border-radius: 50%;
  background: var(--yellow);
  color: var(--ink);
  border: 3px solid #15110d;
  box-shadow: 4px 4px 0 #15110d;
  font-family: 'Bungee', sans-serif;
  font-size: 26px;
  pointer-events: auto;
  touch-action: manipulation;
}

.touch-use:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #15110d; }

.look-hint {
  position: absolute;
  left: 50%;
