}

.look-hint.show { opacity: 0.8; }

.orientation {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%) rotate(-2deg);
  z-index: 150;
  padding: 16px 22px;
  background: var(--paper);
  color: var(--ink);
  border: 3px solid var(--ink);
