  scene.add(visitorsGroup);
  const crowdGroup = new THREE.Group();
  scene.add(crowdGroup);

  const world = {
    scene,
    room,
    camera: null,
    door: { pivot: doorPivot, mesh: doorMesh, open: 0, target: 0 },
    letter,
    letterGlow,
    visitorsGroup,
    crowdGroup,
    decor,
    balloons,
    banner,
    streamers,
    snacks,
    disco,
    discoCord,
    confetti,
    confettiVel: cvel,
    lights: { hemi, room: roomLight, fill: fillLight, tv: tvLight, porch: porchLight, moon, party: partyLights, street: streetGlow },
    tv,
    cat,
    porch,
    partyLevel: 0,
    horror: false,
    t: 0,
  };

  world.setPartyLevel = (level) => {
    world.partyLevel = level;
    balloons.visible = level >= 1;
    snacks.visible = level >= 2;
    banner.visible = level >= 3;
    streamers.visible = level >= 4;
    disco.visible = level >= 5;
    discoCord.visible = level >= 5;
    confetti.visible = level >= 5;
    // reveal balloons progressively
    if (balloons.visible) {
      const show = Math.min(balloonSpots.length, level * 3);
      balloons.children.forEach((child, i) => {
        const idx = Math.floor(i / 2);
        child.visible = idx < show;
      });
    }
  };

  world.setDoorOpen = (v) => { world.door.target = v; };

  world.update = (t, dt) => {
    world.t = t;
    // door spring
    const d = world.door;
    d.open += (d.target - d.open) * Math.min(1, dt * 6.5);
    d.pivot.rotation.y = d.open * 1.9;

    // TV static flicker
    if (world.tvTimer === undefined) world.tvTimer = 0;
    world.tvTimer += dt;
    if (world.tvTimer > 0.11) {
      world.tvTimer = 0;
      const mode = world.horror ? 'dead' : (world.partyLevel >= 5 ? 'party' : 'static');
      world.tv.draw(t, mode);
      world.tv.texture.needsUpdate = true;
    }
    tvLight.intensity = 3 + Math.random() * (world.horror ? 1 : 4);

    // letter ring
    if (world.letterGlow.visible) {
      const s = 1 + Math.sin(t * 3.2) * 0.08;
      world.letterGlow.scale.setScalar(s);
      world.letterGlow.material.opacity = 0.3 + (Math.sin(t * 3.2) + 1) * 0.13;
    }

    // cat tail
    if (world.cat.userData.tail) {
      world.cat.userData.tail.rotation.x = 0.8 + Math.sin(t * 1.6) * 0.2;
    }

    // disco spin
    if (disco.visible) {
      disco.rotation.y += dt * 0.8;
      disco.rotation.x += dt * 0.3;
    }

    // confetti
    if (confetti.visible) {
      const pos = confetti.geometry.attributes.position;
      for (let i = 0; i < confettiCount; i++) {
        let y = pos.array[i * 3 + 1] - cvel[i] * dt;
        if (y < 0.02) y = 3.1;
        pos.array[i * 3 + 1] = y;
        pos.array[i * 3] += Math.sin(t * 1.4 + i) * dt * 0.12;
      }
      pos.needsUpdate = true;
    }

    // party light cycle
    if (world.partyLevel >= 5 && !world.horror) {
      const colors = [0xff4d4d, 0x55d36a, 0x5c7cff, 0xffd24d, 0xff5bd0];
      partyLights.forEach((l, i) => {
        l.intensity = 13 + Math.sin(t * 2.4 + i * 2) * 8;
        l.color.setHex(colors[(Math.floor(t * 1.3) + i) % colors.length]);
      });
      roomLight.color.setHSL((t * 0.07) % 1, 0.55, 0.62);
      roomLight.intensity = 20 + Math.sin(t * 3) * 8;
    }
  };

  return world;
}

/* Everything you hear is made from oscillators and noise. Sorry. */

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.ambienceGain = null;
    this.noiseBuffer = null;
    this.mode = 'ambient';
    this.partyLevel = 0;
    this.muted = false;
    this.started = false;
    this.totalStep = 0;
    this.nextNoteTime = 0;
    this.timer = null;
    this.horrorNodes = null;
    this.crowdSource = null;
    this.voices = 0;
  }

  async init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') await this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 20;
    comp.ratio.value = 5;
    comp.attack.value = 0.004;
    comp.release.value = 0.25;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.0;
    this.musicGain.connect(this.master);

    this.ambienceGain = this.ctx.createGain();
    this.ambienceGain.gain.value = 0.42;
    this.ambienceGain.connect(this.master);

    this.noiseBuffer = this.makeNoise(2.2);
    this.startAmbience();
    this.startScheduler();
    this.started = true;
    if (this.ctx.state === 'suspended') await this.ctx.resume();
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = 0.96 * last + 0.04 * white;
      data[i] = white * 0.7 + last * 0.3;
    }
    return buffer;
  }

  noiseSource(loop = false) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = loop;
    return src;
  }

  startAmbience() {
    const ctx = this.ctx;
    const now = ctx.currentTime;

    // low room tone
    const drone = ctx.createOscillator();
    drone.type = 'sine';
    drone.frequency.value = 48;
    const dg = ctx.createGain();
    dg.gain.value = 0.05;
    const dlp = ctx.createBiquadFilter();
    dlp.type = 'lowpass';
    dlp.frequency.value = 120;
    drone.connect(dlp).connect(dg).connect(this.ambienceGain);
    drone.start(now);

    const drone2 = ctx.createOscillator();
    drone2.type = 'triangle';
    drone2.frequency.value = 73.4;
    const dg2 = ctx.createGain();
    dg2.gain.value = 0.016;
    drone2.connect(dg2).connect(this.ambienceGain);
    drone2.start(now);

    // TV hiss
    const hiss = this.noiseSource(true);
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = 900;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 4200;
    const hg = ctx.createGain();
    hg.gain.value = 0.022;
    hiss.connect(hp).connect(lp).connect(hg).connect(this.ambienceGain);
    hiss.start(now);

    // party crowd murmur (only audible once party begins)
    const crowd = this.noiseSource(true);
    const cf = ctx.createBiquadFilter();
    cf.type = 'bandpass';
    cf.frequency.value = 420;
    cf.Q.value = 0.7;
    const cg = ctx.createGain();
    cg.gain.value = 0.0;
    crowd.connect(cf).connect(cg).connect(this.ambienceGain);
    crowd.start(now);
    this.crowdGain = cg;
    this.crowdSource = crowd;

    // slow LFO on the crowd
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.17;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.012;
    lfo.connect(lfoGain).connect(cg.gain);
    lfo.start(now);
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ctx) return;
    this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.05);
  }

  startScheduler() {
    this.nextNoteTime = this.ctx.currentTime + 0.12;
    this.timer = setInterval(() => {
      if (!this.ctx) return;
      const ahead = 0.18;
      while (this.nextNoteTime < this.ctx.currentTime + ahead) {
        const dur = this.mode === 'horror' ? 0.18 : 60 / 118 / 2;
        this.scheduleStep(this.totalStep, this.nextNoteTime, dur);
        this.totalStep++;
        this.nextNoteTime += dur;
      }
    }, 30);
  }

  scheduleStep(step, time, dur) {
    if (this.mode === 'party') this.scheduleParty(step, time, dur);
    else if (this.mode === 'horror') this.scheduleHorror(step, time, dur);
  }

  scheduleParty(step, time, dur) {
    const s = step % 16;
    const bar = Math.floor(step / 16) % 4;
    const prog = [
      { root: 110.0, notes: [220.0, 261.63, 329.63], lead: [440, 523.25, 659.25, 523.25, 440, 392, 329.63, 392] },
      { root: 87.31, notes: [174.61, 220.0, 261.63], lead: [349.23, 440, 523.25, 440, 349.23, 329.63, 261.63, 329.63] },
      { root: 130.81, notes: [261.63, 329.63, 392.0], lead: [523.25, 659.25, 783.99, 659.25, 523.25, 466.16, 392, 466.16] },
      { root: 98.0, notes: [196.0, 246.94, 293.66], lead: [392, 493.88, 587.33, 493.88, 392, 349.23, 293.66, 349.23] },
    ][bar];
    const level = this.partyLevel;
    const gain = 0.3 + level * 0.7;

    // kick
    if (s % 4 === 0) {
      this.kick(time, 0.5 * gain);
    }
    // snare
    if (s === 4 || s === 12) {
      this.snare(time, 0.22 * gain);
    }
    // hats
    if (level > 0.15 && s % 2 === 1) {
      this.hat(time, 0.07 * gain);
    }
    // bass
    const bassSteps = [0, 3, 6, 8, 11, 14];
    if (bassSteps.includes(s)) {
      const mult = s === 3 || s === 11 ? 1.5 : (s === 6 || s === 14 ? 2 : 1);
      this.musicTone(time, prog.root * mult, dur * 0.8, 'triangle', 0.16 * gain, { filter: 700 });
    }
    // chord stab
    if (level > 0.18 && (s === 0 || s === 6 || s === 10)) {
      prog.notes.forEach((f, i) => {
        this.musicTone(time, f, dur * 0.55, 'square', 0.022 * gain, { filter: 1400, detune: i * 2 });
      });
    }
    // lead
    if (level > 0.34 && s % 2 === 0) {
      const note = prog.lead[(s / 2) | 0];
      this.musicTone(time, note, dur * 0.8, 'sawtooth', 0.055 * gain, { filter: 1900, vibrato: true });
    }
    // sparkle at the top
    if (level >= 1 && s === 15) {
      this.musicTone(time, 1046.5, 0.16, 'sine', 0.05, {});
    }
    if (this.crowdGain) {
      this.crowdGain.gain.setTargetAtTime(level * 0.045, time, 0.4);
    }
  }

  scheduleHorror(step, time, dur) {
    const s = step % 16;
    if (s === 0) {
      this.musicTone(time, 38.5, 1.6, 'sawtooth', 0.09, { filter: 90, detune: -8 });
      this.musicTone(time, 39.5, 1.6, 'sawtooth', 0.07, { filter: 120, detune: 9 });
    }
    if (s === 8) {
      this.musicTone(time, 41.2, 1.3, 'triangle', 0.05, { filter: 200 });
    }
    if (s === 3 || s === 11) {
      const notes = [311.13, 329.63, 466.16, 622.25];
      this.musicTone(time, notes[(step >> 2) % notes.length], 0.22, 'square', 0.026, { filter: 900 });
    }
    if (Math.random() < 0.06) this.whisper(0.2);
    if (this.crowdGain) this.crowdGain.gain.setTargetAtTime(0.0, time, 0.6);
  }

  musicTone(time, freq, dur, type = 'sine', gain = 0.1, opts = {}) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, time);
    if (opts.detune) osc.detune.setValueAtTime(opts.detune, time);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, time);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), time + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, time + Math.max(0.03, dur));
    let node = osc;
    if (opts.filter) {
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = opts.filter;
      f.Q.value = 0.7;
      node.connect(f);
      node = f;
    }
    node.connect(g);
    g.connect(this.musicGain);
    osc.start(time);
    osc.stop(time + dur + 0.05);
    if (opts.vibrato) {
      const lfo = ctx.createOscillator();
      lfo.frequency.value = 5.2;
      const lg = ctx.createGain();
      lg.gain.value = 2.5;
      lfo.connect(lg);
      lg.connect(osc.detune);
      lfo.start(time);
      lfo.stop(time + dur + 0.05);
    }
  }

  kick(time, gain = 0.5) {
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(130, time);
    osc.frequency.exponentialRampToValueAtTime(38, time + 0.12);
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, time);
    g.gain.exponentialRampToValueAtTime(0.001, time + 0.24);
    osc.connect(g).connect(this.musicGain);
    osc.start(time);
    osc.stop(time + 0.26);
  }

  snare(time, gain = 0.2) {
    const ctx = this.ctx;
    const src = this.noiseSource();
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = 1900;
    f.Q.value = 0.8;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, time);
    g.gain.exponentialRampToValueAtTime(0.001, time + 0.18);
    src.connect(f).connect(g).connect(this.musicGain);
    src.start(time);
    src.stop(time + 0.2);
  }

  hat(time, gain = 0.06) {
    const ctx = this.ctx;
    const src = this.noiseSource();
    const f = ctx.createBiquadFilter();
    f.type = 'highpass';
    f.frequency.value = 7500;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, time);
    g.gain.exponentialRampToValueAtTime(0.001, time + 0.05);
    src.connect(f).connect(g).connect(this.musicGain);
    src.start(time);
    src.stop(time + 0.06);
  }

  /* ---------------- one shots ---------------- */

  knock(count = 3) {
    if (!this.ctx) return;
    const t0 = this.ctx.currentTime + 0.02;
    for (let i = 0; i < count; i++) {
      const t = t0 + i * 0.19;
      const osc = this.ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(96, t);
      osc.frequency.exponentialRampToValueAtTime(42, t + 0.16);
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.5, t + 0.008);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.28);
      osc.connect(g).connect(this.master);
      osc.start(t);
      osc.stop(t + 0.3);
      const src = this.noiseSource();
      const f = this.ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = 700;
      const ng = this.ctx.createGain();
      ng.gain.setValueAtTime(0.18, t);
      ng.gain.exponentialRampToValueAtTime(0.001, t + 0.14);
      src.connect(f).connect(ng).connect(this.master);
      src.start(t);
      src.stop(t + 0.15);
    }
  }

  click() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = 'square';
    osc.frequency.setValueAtTime(640, t);
    osc.frequency.exponentialRampToValueAtTime(220, t + 0.06);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.06, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    osc.connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + 0.09);
  }

  doorCreak(open = true) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(open ? 90 : 240, t);
    osc.frequency.exponentialRampToValueAtTime(open ? 250 : 70, t + 0.75);
    const f = this.ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.setValueAtTime(800, t);
    f.frequency.exponentialRampToValueAtTime(300, t + 0.8);
    f.Q.value = 5;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.07, t + 0.1);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.9);
    osc.connect(f).connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + 0.95);
  }

  doorSlam() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const src = this.noiseSource();
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = 420;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.5, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
    src.connect(f).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + 0.36);
    const osc = this.ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(80, t);
    osc.frequency.exponentialRampToValueAtTime(30, t + 0.4);
    const og = this.ctx.createGain();
    og.gain.setValueAtTime(0.45, t);
    og.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
    osc.connect(og).connect(this.master);
    osc.start(t);
    osc.stop(t + 0.52);
  }

  step() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const src = this.noiseSource();
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = 260;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.05, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    src.connect(f).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + 0.13);
  }

  voice(kind = 'human') {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + 0.02;
    const count = 3 + ((Math.random() * 3) | 0);
    const base = kind === 'human' ? 150 + Math.random() * 90 : 62 + Math.random() * 24;
    for (let i = 0; i < count; i++) {
      const st = t + i * 0.09;
      const osc = this.ctx.createOscillator();
      osc.type = kind === 'human' ? 'triangle' : 'sawtooth';
      osc.frequency.setValueAtTime(base * (1 + Math.random() * 0.1), st);
      osc.frequency.exponentialRampToValueAtTime(base * (0.8 + Math.random() * 0.35), st + 0.08);
      const f = this.ctx.createBiquadFilter();
      f.type = 'bandpass';
      f.frequency.value = kind === 'human' ? 700 : 220;
      f.Q.value = 3;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, st);
      g.gain.exponentialRampToValueAtTime(kind === 'human' ? 0.055 : 0.075, st + 0.01);
      g.gain.exponentialRampToValueAtTime(0.001, st + 0.085);
      osc.connect(f).connect(g).connect(this.master);
      osc.start(st);
      osc.stop(st + 0.1);
    }
    if (kind !== 'human') {
      this.whisper(0.18);
    }
  }

  whisper(dur = 0.4) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const src = this.noiseSource();
    const f = this.ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.setValueAtTime(1100, t);
    f.frequency.linearRampToValueAtTime(2400, t + dur);
    f.Q.value = 4;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.035, t + 0.06);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.05);
  }

  cheer() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const src = this.noiseSource();
    const f = this.ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.setValueAtTime(700, t);
    f.frequency.linearRampToValueAtTime(1800, t + 0.5);
    f.Q.value = 0.8;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.12, t + 0.08);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.9);
    src.connect(f).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + 0.95);
    [523.25, 659.25, 783.99].forEach((freq, i) => {
      this.musicTone(t + i * 0.05, freq, 0.25, 'triangle', 0.045, {});
    });
  }

  scare() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    // sub boom
    const sub = this.ctx.createOscillator();
    sub.type = 'sine';
    sub.frequency.setValueAtTime(70, t);
    sub.frequency.exponentialRampToValueAtTime(24, t + 1.1);
    const subG = this.ctx.createGain();
    subG.gain.setValueAtTime(0.75, t);
    subG.gain.exponentialRampToValueAtTime(0.001, t + 1.2);
    sub.connect(subG).connect(this.master);
    sub.start(t);
    sub.stop(t + 1.2);

    // screaming cluster
    for (let i = 0; i < 4; i++) {
      const osc = this.ctx.createOscillator();
      osc.type = i % 2 ? 'sawtooth' : 'square';
      const freq = 220 + i * 95 + Math.random() * 80;
      osc.frequency.setValueAtTime(freq, t);
      osc.frequency.exponentialRampToValueAtTime(freq * (1.6 + Math.random() * 0.5), t + 0.35);
      osc.frequency.exponentialRampToValueAtTime(freq * 0.55, t + 1.0);
      const f = this.ctx.createBiquadFilter();
      f.type = 'bandpass';
      f.frequency.value = 900 + i * 300;
      f.Q.value = 1.8;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.12, t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, t + 1.05);
      osc.connect(f).connect(g).connect(this.master);
      osc.start(t);
      osc.stop(t + 1.1);
    }

    // noise blast
    const src = this.noiseSource();
    const f = this.ctx.createBiquadFilter();
    f.type = 'highpass';
    f.frequency.value = 600;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.22, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.8);
    src.connect(f).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + 0.85);
  }

  boom() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(60, t);
    osc.frequency.exponentialRampToValueAtTime(22, t + 1.4);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.6, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 1.5);
    osc.connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + 1.5);
  }

  jingle() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const notes = [523.25, 659.25, 783.99, 1046.5, 783.99, 1046.5];
    notes.forEach((f, i) => {
      this.musicTone(t + i * 0.13, f, 0.28, 'triangle', 0.08, {});
      this.musicTone(t + i * 0.13, f * 2, 0.22, 'sine', 0.03, {});
    });
    this.cheer();
  }

  badJingle() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const notes = [392, 370, 349.23, 329.63, 311.13, 220];
    notes.forEach((f, i) => {
      this.musicTone(t + i * 0.16, f, 0.3, 'sawtooth', 0.04, { filter: 900 });
    });
  }

  setMode(mode) {
    if (this.mode === mode) return;
    this.mode = mode;
    if (mode === 'party') {
      this.musicGain.gain.setTargetAtTime(0.06 + this.partyLevel * 0.17, this.ctx ? this.ctx.currentTime : 0, 0.8);
    } else if (mode === 'horror') {
      this.musicGain.gain.setTargetAtTime(0.22, this.ctx ? this.ctx.currentTime : 0, 0.4);
      if (this.ctx) {
        this.musicGain.gain.cancelScheduledValues(this.ctx.currentTime);
        this.musicGain.gain.setTargetAtTime(0.2, this.ctx.currentTime, 0.3);
      }
    } else {
      this.musicGain.gain.setTargetAtTime(0.0, this.ctx ? this.ctx.currentTime : 0, 0.8);
    }
  }

  setPartyLevel(level) {
    this.partyLevel = Math.max(0, Math.min(1, level));
    if (!this.ctx) return;
    if (this.mode !== 'horror' && this.mode !== 'win') {
      if (this.partyLevel > 0 && this.mode !== 'party') this.setMode('party');
      if (this.mode === 'party') {
        this.musicGain.gain.setTargetAtTime(0.06 + this.partyLevel * 0.18, this.ctx.currentTime, 0.5);
      }
    }
    if (this.crowdGain) {
      this.crowdGain.gain.setTargetAtTime(this.partyLevel * 0.05, this.ctx.currentTime, 0.6);
    }
  }

  stopMusic() {
    this.mode = 'ambient';
    if (this.ctx) this.musicGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.2);
  }

  dispose() {
    if (this.timer) clearInterval(this.timer);
    if (this.ctx) this.ctx.close();
  }
}

/* THE DOOR — a game about standing at a door.
   Built quickly, on purpose. */

import * as THREE from '../vendor/three.module.js';
import { buildWorld } from './world.js';
import {
  createPerson, makeVisitorSpec, makeHumanSpec, makeAnomalySpec,
  animatePerson, addDeath, reactPerson,
} from './visitors.js';
import { AudioEngine } from './audio.js';
import { anomalyFaceSpec, faceCanvas } from './textures.js';

const $ = (id) => document.getElementById(id);
const els = {
  canvas: $('scene'), hud: $('hud'),
  guestCount: $('guest-count'), guestBar: $('guest-bar-fill'), guestSub: $('guest-sub'),
  objective: $('objective-text'), clock: $('clock'), doorStatus: $('door-status'),
  prompt: $('prompt'), subtitle: $('subtitle'), toast: $('toast'),
  title: $('title-screen'), start: $('start-btn'),
  letterScreen: $('letter-screen'), letterOk: $('letter-ok'),
  doorUI: $('door-ui'), doorPrompt: $('door-prompt-text'),
  peepBtn: $('peep-btn'), openBtn: $('open-btn'),
  peepUI: $('peep-ui'), peepGuests: $('peep-guests'), mask: $('peephole-mask'),
  speech: $('speech'), speaker: $('speaker'), line: $('line'),
  flashBtn: $('flash-btn'), knockBtn: $('knock-btn'), zoomBtn: $('zoom-btn'), backBtn: $('back-btn'),
  acceptBtn: $('accept-btn'), rejectBtn: $('reject-btn'),
  partyBanner: $('party-banner'), jumpscare: $('jumpscare'), killingTitle: $('killing-title'),
  ending: $('ending'), endingStamp: $('ending-stamp'), endingTitle: $('ending-title'),
  endingSub: $('ending-sub'), endingStats: $('ending-stats'), endingReview: $('ending-review'),
  restart: $('restart-btn'), mute: $('mute'),
  mobile: $('mobile-controls'), stickZone: $('stick-zone'), stickKnob: $('stick-knob'), touchUse: $('touch-use'),
  lookHint: $('look-hint'),
  flash: $('flash'), static: $('static'),
};

const audio = new AudioEngine();
const world = buildWorld();
const scene = world.scene;
world.lights.porch.intensity = 0;
world.lights.street.intensity = 10;

const renderer = new THREE.WebGLRenderer({ canvas: els.canvas, antialias: false, powerPreference: 'high-performance' });
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.shadowMap.enabled = false;
renderer.setPixelRatio(1);

const camera = new THREE.PerspectiveCamera(70, 1, 0.04, 90);
camera.rotation.order = 'YXZ';

const isTouch = window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0;
const portrait = () => window.innerWidth < window.innerHeight * 0.86;

function resize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  const scale = w < 760 ? 0.58 : 0.52;
  const rw = Math.max(260, Math.round(w * scale));
  const rh = Math.max(200, Math.round(h * scale));
  renderer.setSize(rw, rh, false);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
}
window.addEventListener('resize', resize);
resize();

/* ------------------------------------------------------------------ */
/* state                                                              */
/* ------------------------------------------------------------------ */

const State = {
  TITLE: 'title', INTRO: 'intro', LETTER: 'letter', DOOR: 'door',
  PEEP: 'peep', ANIM: 'anim', PARTY: 'party', DEATH: 'death', WIN: 'win',
};

let state = State.TITLE;
let guests = 0;
let turnedAway = 0;
let anomaliesRejected = 0;
let anomaliesAdmitted = 0;
let rounds = 0;
let current = null;
let crowd = [];
let roundSeq = 0;
let finalRound = false;
let partyTimer = 0;
let doorPhaseStart = 0;
let runStart = 0;
let endingShown = false;
let lastKnockAt = 0;
let flickerUntil = 0;
let noteAnim = null;
let jitter = 0;

const view = {
  pos: new THREE.Vector3(2.85, 1.62, 3.35),
  yaw: 0.34, pitch: -0.02, fov: 70,
};
let tween = null;
let shake = 0;

const peep = {
  active: false, yaw: 0, pitch: 0, zoom: false, flash: false,
  autoLineAt: 0, knockReadyAt: 0, fired: false,
};

const keys = new Set();
const joy = { x: 0, y: 0, active: false, id: null };
let dragging = false;
let dragId = null;
let lastX = 0;
let lastY = 0;

const DOOR_POS = new THREE.Vector3(0, 1.62, -2.55);
const PEEP_POS = new THREE.Vector3(0, 1.55, -4.58);
const PARTY_POS = new THREE.Vector3(0, 1.74, -3.35);
const INTRO_POS = new THREE.Vector3(0.25, 1.62, 2.75);

/* ------------------------------------------------------------------ */
/* tiny helpers                                                       */
/* ------------------------------------------------------------------ */

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rnd = (a, b) => a + Math.random() * (b - a);
const $set = (el, on) => el.classList.toggle('hidden', !on);

let toastTimer = 0;
function toast(text, ms = 2200) {
  els.toast.textContent = text;
  els.toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => els.toast.classList.remove('show'), ms);
}

let subTimer = 0;
function subtitle(text, ms = 3200) {
  els.subtitle.textContent = text;
  els.subtitle.classList.add('show');
  clearTimeout(subTimer);
  if (ms > 0) subTimer = setTimeout(() => els.subtitle.classList.remove('show'), ms);
}

function clearSubtitle() {
  els.subtitle.classList.remove('show');
  clearTimeout(subTimer);
}

function prompt(text) {
  if (!text) {
    els.prompt.classList.remove('show');
    els.prompt.textContent = '';
    return;
  }
  els.prompt.innerHTML = text;
  els.prompt.classList.add('show');
}

function setObjective(text) {
  els.objective.textContent = text;
}

function releaseLook() {
  if (document.pointerLockElement === els.canvas) document.exitPointerLock();
}

function flashScreen(red = false) {
  els.flash.classList.toggle('red', red);
  els.flash.classList.remove('on');
  void els.flash.offsetWidth;
  els.flash.classList.add('on');
  setTimeout(() => els.flash.classList.remove('on'), 620);
}

function fmtTime(total) {
  let h = Math.floor(total / 60) % 24;
  const m = Math.floor(total % 60);
  const ap = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return `${h}:${String(m).padStart(2, '0')} ${ap}`;
}

function updateHud() {
  els.guestCount.textContent = String(guests);
  els.guestBar.style.width = `${Math.min(100, (guests / 50) * 100)}%`;
  els.clock.textContent = fmtTime(20 * 60 + 14 + guests * 5 + turnedAway * 2);
  els.peepGuests.textContent = `GUESTS ${guests}/50`;
  if (guests >= 50) els.guestSub.textContent = '50 humans. it is a party.';
  else if (guests >= 36) els.guestSub.textContent = 'almost 50 humans';
  else if (guests >= 20) els.guestSub.textContent = 'the party is growing';
  else if (guests >= 8) els.guestSub.textContent = 'it is becoming a party';
  else els.guestSub.textContent = 'let the humans in';
}

function setState(next) {
  state = next;
  const peeping = next === State.PEEP;
  $set(els.mask, peeping);
  $set(els.peepUI, peeping);
  $set(els.doorUI, next === State.DOOR);
  $set(els.mobile, next === State.INTRO && isTouch);
  els.doorStatus.textContent = world.door.target > 0.5 ? 'DOOR: OPEN' : 'DOOR: CLOSED';
  if (next === State.DOOR || next === State.PEEP || next === State.PARTY || next === State.DEATH) releaseLook();
}

function tweenView(toPos, yaw, pitch, fov = 70, dur = 1.0, onDone = null) {
  tween = {
    fromPos: view.pos.clone(), toPos: toPos.clone(),
    fromYaw: view.yaw, toYaw: yaw,
    fromPitch: view.pitch, toPitch: pitch,
    fromFov: view.fov, toFov: fov,
    t: 0, dur: Math.max(0.01, dur), onDone,
  };
}

function updateTween(dt) {
  if (!tween) return;
  tween.t += dt;
  const k = clamp(tween.t / tween.dur, 0, 1);
  const e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
  view.pos.lerpVectors(tween.fromPos, tween.toPos, e);
  view.yaw = tween.fromYaw + (tween.toYaw - tween.fromYaw) * e;
  view.pitch = tween.fromPitch + (tween.toPitch - tween.fromPitch) * e;
  view.fov = tween.fromFov + (tween.toFov - tween.fromFov) * e;
  if (k >= 1) {
    const done = tween.onDone;
    tween = null;
    if (done) done();
  }
}

/* ------------------------------------------------------------------ */
/* title + letter                                                     */
/* ------------------------------------------------------------------ */

async function startGame() {
  if (state !== State.TITLE) return;
  $set(els.title, false);
  $set(els.hud, true);
  audio.init().catch(() => {});
  runStart = performance.now();
  state = State.INTRO;
  setState(State.INTRO);
  updateHud();
  setObjective('walk to the letter');
  view.pos.set(2.85, 1.62, 3.35);
  view.yaw = 0.34;
  view.pitch = -0.02;
  tweenView(INTRO_POS, 0.0, 0.0, 70, 1.25);
  subtitle('your house. 8:14 PM. nothing is wrong.', 3800);
  toast('the letter is by the door.', 2800);
  setTimeout(() => {
    els.lookHint.classList.remove('hidden');
    els.lookHint.classList.add('show');
    setTimeout(() => els.lookHint.classList.remove('show'), 7000);
  }, 1400);
  updateHud();
}

function openLetter() {
  if (state !== State.INTRO) return;
  releaseLook();
  state = State.LETTER;
  $set(els.letterScreen, true);
  $set(els.hud, false);
  $set(els.mobile, false);
  audio.click();
  prompt('');
}

function closeLetter() {
  if (state !== State.LETTER) return;
  $set(els.letterScreen, false);
  $set(els.hud, true);
  state = State.DOOR;
  setState(State.DOOR);
  view.pos.copy(DOOR_POS);
  view.yaw = 0;
  view.pitch = 0;
  view.fov = 70;
  world.letter.visible = false;
  world.letterGlow.visible = false;
  doorPhaseStart = performance.now();
  setObjective('stand at the door');
  audio.click();
  audio.doorSlam();
  shake = 0.035;
  flickerUntil = performance.now() / 1000 + 0.9;
  setTimeout(() => {
    if (state !== State.DOOR) return;
    world.lights.porch.intensity = 22;
    audio.boom();
    subtitle('...', 1200);
  }, 500);
  setTimeout(() => {
    if (state !== State.DOOR) return;
    beginRound();
  }, 2200);
}

/* ------------------------------------------------------------------ */
/* round building                                                     */
/* ------------------------------------------------------------------ */

function disposePerson(p) {
  p.traverse((o) => {
    if (!o.isMesh) return;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    for (const m of mats) {
      if (!m) continue;
      if (m.map && m.map.dispose) m.map.dispose();
      m.dispose();
    }
  });
  if (p.parent) p.parent.remove(p);
}

function clearVisitors() {
  for (const p of [...world.visitorsGroup.children]) disposePerson(p);
  current = null;
  peep.fired = false;
  peep.active = false;
  $set(els.speech, false);
}

function layoutVisitor(i, n) {
  if (portrait()) {
    if (n <= 2) return { x: (i - (n - 1) / 2) * 0.52, z: -6.28 };
    const row = i % 2;
    const col = Math.floor(i / 2);
    const rowCount = Math.ceil(n / 2);
    return { x: (col - (rowCount - 1) / 2) * 0.58, z: -6.05 - row * 0.72 };
  }
  return { x: (i - (n - 1) / 2) * 0.58, z: -6.3 - (i % 2) * 0.1 };
}

function buildVisitors(spec) {
  const n = spec.people.length;
  const people = [];
  spec.people.forEach((ps, i) => {
    const p = createPerson(ps);
    const pos = layoutVisitor(i, n);
    p.position.set(pos.x, 0, pos.z);
    p.rotation.y = 0;
    world.visitorsGroup.add(p);
    people.push(p);
  });
  const first = spec.people[0];
  const name = first.kind === 'anomaly' ? '???' : first.name.toUpperCase();
  const extra = spec.people.length > 1 ? ` + ${spec.people.length - 1}` : '';
  return {
    spec,
    people,
    isAnomaly: spec.people.some((p) => p.kind === 'anomaly'),
    anomalyPerson: people.find((p) => p.userData.isAnomaly) || null,
    speaker: name + extra,
    line: first.line,
    final: false,
  };
}

function beginRound(forceKind = null, forceTell = null, opts = {}) {
  if (state === State.DEATH || state === State.WIN || state === State.PARTY) return;
  clearVisitors();
  $set(els.ending, false);
  rounds += 1;
  const seq = ++roundSeq;

  let anomaly = false;
  if (forceKind === 'anomaly') anomaly = true;
  else if (forceKind === 'human') anomaly = false;
  else if (rounds > 2) anomaly = Math.random() < (0.24 + Math.min(0.16, (guests / 50) * 0.16));

  const spec = makeVisitorSpec({ anomaly, guests, primary: forceTell });
  current = buildVisitors(spec);
  current.final = Boolean(opts.final);
  finalRound = Boolean(opts.final);

  setState(State.DOOR);
  view.pos.copy(DOOR_POS);
  view.yaw = 0;
  view.pitch = 0;
  view.fov = 70;
  setObjective(opts.final ? 'one last guest' : 'someone is at the door');
  els.doorPrompt.textContent = opts.final ? 'someone is at the door. (last one.)' : 'someone is at the door.';
  updateHud();
  audio.knock(3);
  shake = 0.02;
  if (seq !== roundSeq) return;
}

