    this.musicGain = null;
    this.ambienceGain = null;
    this.noiseBuffer = null;
    this.mode = 'ambient';
    this.partyLevel = 0;
    this.muted = false;
    this.started = false;
    this.totalStep = 0;
    this.nextNoteTime = 0;
    this.timer = null;
    this.horrorNodes = null;
    this.crowdSource = null;
    this.voices = 0;
